const webhookItem = $('Consultar disponibilidade').first().json || {};
const q = webhookItem.query || {};
const date = q.date || new Date().toISOString().slice(0,10);
const staticData = $getWorkflowStaticData('global');

// Multi-tenant: lê clientId da query ?client= ou ?clientId=
const clientId = String(q.client || q.clientId || 'default').toLowerCase().replace(/[^a-z0-9_-]/g,'') || 'default';
const clientCfg = staticData.clients?.[clientId]?.businessConfig || {};
const legacyCfg = clientId === 'default' ? (staticData.businessConfig || {}) : {};
const cfg = { closedWeekdays:[0], blockFrom:'', blockTo:'', startHour:'08:00', endHour:'20:00', slotMin:30, ...legacyCfg, ...clientCfg };

const service = String(q.service || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const durationMin = service.includes('combo') || (service.includes('corte') && service.includes('barba')) ? 60 : 30;
const cfgSlotMin = Number(cfg.slotMin) || 30;
const stepMin = Math.max(cfgSlotMin, durationMin); // avança pelo menos a duração do serviço

const busy = $input.all().map(i => i.json).filter(e => e && (e.start || e.id));
const day = new Date(date + 'T12:00:00-03:00');
// Bloquear datas passadas
const todayLocal = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });
if (date < todayLocal) return [{ json: { date, service, durationMin, stepMin, blocked: true, reason: 'Data no passado', slots: [] } }];
const dow = day.getDay();
const blockedByWeekday = (cfg.closedWeekdays || [0]).map(Number).includes(dow);
const blockedByPeriod = cfg.blockFrom && cfg.blockTo && date >= cfg.blockFrom && date <= cfg.blockTo;
if (blockedByWeekday || blockedByPeriod) return [{ json: { date, service, durationMin, stepMin, blocked: true, reason: blockedByPeriod ? (cfg.blockReason || 'Profissional indisponível neste período.') : 'Não há atendimento neste dia da semana.', slots: [] } }];

const slots = [];
const [sh,sm] = String(cfg.startHour || '08:00').split(':').map(Number);
const [eh,em] = String(cfg.endHour || '20:00').split(':').map(Number);
const startMinute = (Number.isFinite(sh)?sh:8) * 60 + (Number.isFinite(sm)?sm:0);
const endMinute = (Number.isFinite(eh)?eh:20) * 60 + (Number.isFinite(em)?em:0);

const ocupados = busy.map(e => {
  const s = new Date(e.start?.dateTime || e.start?.date || 0);
  const en = new Date(e.end?.dateTime || e.end?.date || 0);
  return { s, en };
}).filter(x => !isNaN(x.s) && !isNaN(x.en));

for (let minutes = startMinute; minutes + durationMin <= endMinute; minutes += stepMin) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  const hh = String(h).padStart(2,'0');
  const mm = String(m).padStart(2,'0');
  const slotStart = new Date(date + 'T' + hh + ':' + mm + ':00-03:00');
  const slotEnd = new Date(slotStart.getTime() + durationMin * 60 * 1000);
  const taken = ocupados.some(ev => slotStart < ev.en && slotEnd > ev.s);
  if (!taken) slots.push({ label: hh + ':' + mm, iso: slotStart.toISOString(), durationMin });
}
return [{ json: { date, service, durationMin, stepMin, blocked: false, slots } }];

const b = $json.body || $json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();

// ── Honeypot: campo invisível que bots preenchem, humanos não ──
if (String(b._hp || b.website || '').trim()) {
  return [{ json: { valid: false, errors: ['Solicitação bloqueada.'], message: 'Bloqueado.' } }];
}

// ── Rate limiting: máx 5 tentativas por telefone por 10 min ──
const rawPhone = String(b.phone || '').replace(/\D/g,'');
sd.rateLimit = sd.rateLimit || {};
const window10 = 10 * 60 * 1000;
// Limpar entradas antigas
Object.keys(sd.rateLimit).forEach(k => {
  sd.rateLimit[k] = (sd.rateLimit[k] || []).filter(t => t > now - window10);
  if (!sd.rateLimit[k].length) delete sd.rateLimit[k];
});
if (rawPhone.length >= 10) {
  sd.rateLimit[rawPhone] = sd.rateLimit[rawPhone] || [];
  if (sd.rateLimit[rawPhone].length >= 5) {
    return [{ json: { valid: false, errors: ['Muitas tentativas. Aguarde alguns minutos.'], message: 'Rate limit.' } }];
  }
  sd.rateLimit[rawPhone].push(now);
}

// ── Validação de campos ──
const serviceRaw = b.service || 'Servico';
const barber = b.barber || 'Primeiro disponível';
const service = String(serviceRaw).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const durationMin = service.includes('combo') || (service.includes('corte') && service.includes('barba')) ? 60 : 30;
const start = new Date(b.start);
const startValid = b.start && !Number.isNaN(start.getTime());
const end = startValid ? new Date(start.getTime() + durationMin * 60 * 1000) : new Date();
const name = String(b.name || '').trim();
const phone = rawPhone;
const lgpdConsent = b.lgpdConsent === true || b.lgpdConsent === 'true';

const clientId = String(b.clientId || 'default').toLowerCase().replace(/[^a-z0-9_-]/g,'') || 'default';

// ── Auto-registro do cliente no cadastro ──────────────���──────────────────────
if (name && phone && phone.length >= 8) {
  sd.clients = sd.clients || {};
  sd.clients[clientId] = sd.clients[clientId] || {};
  sd.clients[clientId].clientes = sd.clients[clientId].clientes || {};
  const existingCli = sd.clients[clientId].clientes[phone];
  if (!existingCli) {
    sd.clients[clientId].clientes[phone] = {
      name, phone,
      registeredAt: now,
      totalVisits: 0,
      totalSpent: 0,
      lastVisit: null,
      notes: ''
    };
  } else if (existingCli.name === 'Cliente' && name !== 'Cliente') {
    existingCli.name = name;
  }
}
// ── Fim auto-registro ─────────────────────────────────────────────────────────

// Multi-tenant: calendarId e evolutionInstance por cliente
const clientCfg = (sd.clients && sd.clients[clientId] && sd.clients[clientId].businessConfig) || sd.businessConfig || {};
const calendarId = String(clientCfg.calendarId || 'primary');
const evolutionInstance = String(clientCfg.evolutionInstance || 'estudo');

const errors = [];
if (!name || name.length < 2) errors.push('Informe seu nome completo.');
if (!phone || phone.length < 10 || phone.length > 13) errors.push('Informe um WhatsApp válido com DDD.');
if (phone.length >= 10) {
  // DDD brasileiro válido (11-99 exceto alguns reservados)
  const ddd = parseInt(phone.slice(-11, -9), 10) || parseInt(phone.slice(0, 2), 10);
  const dddsValidos = [11,12,13,14,15,16,17,18,19,21,22,24,27,28,31,32,33,34,35,37,38,41,42,43,44,45,46,47,48,49,51,53,54,55,61,62,63,64,65,66,67,68,69,71,73,74,75,77,79,81,82,83,84,85,86,87,88,89,91,92,93,94,95,96,97,98,99];
  if (!dddsValidos.includes(ddd)) errors.push('DDD inválido. Informe um WhatsApp brasileiro válido.');
}
if (!startValid) errors.push('Escolha um horário válido.');
if (startValid && start <= new Date()) errors.push('Esse horário já passou. Escolha um horário futuro.');
// lgpd gate enforced client-side — server check removed

const data_br = startValid ? start.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
const hora_br = startValid ? start.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' }) : '';
const origem = 'Agenda online';
const lgpdStr = lgpdConsent ? 'Sim (aceito via agenda online)' : 'Não informado';
const description = 'Cliente: ' + (name || '') + '\nWhatsApp: ' + phone + '\nServiço: ' + serviceRaw + '\nBarbeiro: ' + barber + '\nDuração: ' + durationMin + ' minutos\nOrigem: ' + origem + '\nConsentimento LGPD: ' + lgpdStr + '\nInstanciaWA: ' + evolutionInstance + '\nClienteID: ' + clientId;
return [{ json: { clientId, calendarId, evolutionInstance, eventId: b.eventId || '', valid: errors.length === 0, errors, name: name || 'Cliente', phone, service: serviceRaw, barber, durationMin, lgpdConsent, start_iso: startValid ? start.toISOString() : '', end_iso: startValid ? end.toISOString() : '', data_br, hora_br, summary: 'Barbearia - ' + serviceRaw + ' - ' + (name || 'Cliente'), description } }];

const q = $('Buscar meus agendamentos').first().json?.query
       || $('Buscar meus agendamentos').first().json?.body
       || $('Buscar meus agendamentos').first().json || {};
const phone = String(q.phone || '').replace(/\D/g,'');
const otp = String(q.otp || '').replace(/\D/g,'').trim();

// ── Verificação OTP ──
if (phone.length >= 10) {
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  sd.verifiedPhones = sd.verifiedPhones || {};
  const vp = sd.verifiedPhones[phone];

  if (vp && vp.expires > now) {
    // Sessão ativa — continua normalmente
  } else if (otp) {
    sd.otps = sd.otps || {};
    const stored = sd.otps[phone];
    if (!stored || stored.expires < now) {
      return [{ json: { needsCode: true, events: [], message: 'Código expirado. Solicite um novo.' } }];
    }
    if (stored.code !== otp) {
      return [{ json: { needsCode: true, events: [], message: 'Código inválido. Tente novamente.' } }];
    }
    // Código correto — criar sessão verificada por 2h
    sd.verifiedPhones[phone] = { expires: now + 2 * 60 * 60 * 1000 };
    delete sd.otps[phone];
  } else {
    return [{ json: { needsCode: true, events: [], message: 'Confirme seu número via código enviado no WhatsApp.' } }];
  }
}

const events = $input.all().map(i => i.json).filter(e => e && e.id && String(e.description || '').replace(/\D/g,'').includes(phone));
return [{ json: { events: events.map(e => {
  const start = e.start?.dateTime || e.start?.date;
  const desc = e.description || '';
  const name = (desc.match(/Cliente:\s*([^\n]*)/) || [,'Cliente'])[1].trim() || 'Cliente';
  const service = (desc.match(/Servi.o:\s*([^\n]*)/) || [,'Agendamento'])[1].trim() || String(e.summary || 'Agendamento').replace(/^Barbearia - /,'').split(' - ')[0];
  const barber = (desc.match(/Barbeiro:\s*([^\n]*)/) || [,'Primeiro disponível'])[1].trim() || 'Primeiro disponível';
  return { id: e.id, name, service, barber, start, when: new Date(start).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) };
}) } }];

const b = $json.body || $json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const clientId = String(b.clientId || 'default').toLowerCase().replace(/[^a-z0-9_-]/g,'') || 'default';

// Multi-tenant: calendarId e evolutionInstance por cliente
const clientCfg = (sd.clients && sd.clients[clientId] && sd.clients[clientId].businessConfig) || sd.businessConfig || {};
const calendarId = String(clientCfg.calendarId || 'primary');
const evolutionInstance = String(clientCfg.evolutionInstance || 'estudo');

// ── Honeypot ──
if (String(b._hp || b.website || '').trim()) {
  return [{ json: { valid: false, errors: ['Solicitação bloqueada.'], message: 'Bloqueado.' } }];
}

// ── Rate limiting: máx 5 por telefone por 10 min ──
const rawPhone = String(b.phone || '').replace(/\D/g,'');
sd.rateLimit = sd.rateLimit || {};
const window10 = 10 * 60 * 1000;
Object.keys(sd.rateLimit).forEach(k => {
  sd.rateLimit[k] = (sd.rateLimit[k] || []).filter(t => t > now - window10);
  if (!sd.rateLimit[k].length) delete sd.rateLimit[k];
});
if (rawPhone.length >= 10) {
  sd.rateLimit[rawPhone] = sd.rateLimit[rawPhone] || [];
  if (sd.rateLimit[rawPhone].length >= 5) {
    return [{ json: { valid: false, errors: ['Muitas tentativas. Aguarde alguns minutos.'], message: 'Rate limit.' } }];
  }
  sd.rateLimit[rawPhone].push(now);
}

const serviceRaw = b.service || 'Servico';
const barber = b.barber || 'Primeiro disponível';
const service = String(serviceRaw).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const durationMin = service.includes('combo') || (service.includes('corte') && service.includes('barba')) ? 60 : 30;
const start = new Date(b.start);
const startValid = b.start && !Number.isNaN(start.getTime());
const end = startValid ? new Date(start.getTime() + durationMin * 60 * 1000) : new Date();
const name = String(b.name || '').trim();
const phone = rawPhone;
const errors = [];

if (!b.eventId) errors.push('Escolha um agendamento para remarcar.');
if (!phone || phone.length < 10) errors.push('Informe um WhatsApp válido.');
if (phone.length >= 10) {
  const ddd = parseInt(phone.slice(0,2), 10);
  const dddsValidos = [11,12,13,14,15,16,17,18,19,21,22,24,27,28,31,32,33,34,35,37,38,41,42,43,44,45,46,47,48,49,51,53,54,55,61,62,63,64,65,66,67,68,69,71,73,74,75,77,79,81,82,83,84,85,86,87,88,89,91,92,93,94,95,96,97,98,99];
  if (!dddsValidos.includes(ddd)) errors.push('DDD inválido.');
}
if (!startValid) errors.push('Escolha um horário válido.');

// ── Slot lock ──
if (errors.length === 0 && startValid) {
  sd.slotLocks = sd.slotLocks || {};
  Object.entries(sd.slotLocks).forEach(([k,v]) => { if (v < now - 45000) delete sd.slotLocks[k]; });
  const lockKey = 'slot_' + start.toISOString().slice(0, 16);
  if (sd.slotLocks[lockKey]) {
    errors.push('Este horário está sendo reservado agora. Tente outro horário.');
  } else {
    sd.slotLocks[lockKey] = now;
  }
}

const data_br = startValid ? start.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' }) : '';
const hora_br = startValid ? start.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' }) : '';
const origem = 'Reagendamento online';
const description = 'Cliente: ' + (name || '') + '\nWhatsApp: ' + phone + '\nServiço: ' + serviceRaw + '\nBarbeiro: ' + barber + '\nDuração: ' + durationMin + ' minutos\nOrigem: ' + origem + '\nInstanciaWA: ' + evolutionInstance + '\nClienteID: ' + clientId;
return [{ json: { clientId, calendarId, evolutionInstance, eventId: b.eventId || '', valid: errors.length === 0, errors, name: name || 'Cliente', phone, service: serviceRaw, barber, durationMin, start_iso: startValid ? start.toISOString() : '', end_iso: startValid ? end.toISOString() : '', data_br, hora_br, summary: 'Barbearia - ' + serviceRaw + ' - ' + (name || 'Cliente'), description } }];

// ── Plan/feature detection ──
const PLAN_FEATURES_BOT = {
  iniciante: ['agenda','bot_basico','comandas'],
  profissional: ['agenda','bot_basico','bot_premium','comandas','despesas','reativacao','multi_barber','backup_telegram','relatorios_completos'],
  empresarial: ['agenda','bot_basico','bot_premium','comandas','despesas','reativacao','multi_barber','backup_telegram','relatorios_completos','wa_oficial','multi_unidade','suporte_prioritario']
};
function getBotTier(sd) {
  const cs = sd.clients || {};
  const ids = Object.keys(cs).filter(id => id !== 'superadmin');
  // single-client (provisioned workflow) ou default
  const clientId = ids.length === 1 ? ids[0] : 'default';
  const c = cs[clientId] || {};
  let plan = c.plan || 'profissional';
  if (c.trialExpires && c.trialExpires > Date.now()) plan = c.planTrial || 'profissional';
  const features = PLAN_FEATURES_BOT[plan] || PLAN_FEATURES_BOT.profissional;
  return { plan, features, premium: features.indexOf('bot_premium') >= 0 };
}

// ── Template variations (5 premium, 1 basic por tipo) ──
const TEMPLATES = {
  lembrete24h: {
    basic: ['✂️ Olá, {cliente}! Lembrando do seu horário amanhã na barbearia 💈

📅 {data} às {hora}
✂️ Serviço: {servico}
