function pickTemplate(type, premium, sd, clientId) {
  // ── 🎨 Custom templates do admin têm prioridade ──
  if (sd && clientId) {
    const custom = ((sd.clients||{})[clientId]||{}).customTemplates || {};
    const customList = custom[type];
    if (Array.isArray(customList) && customList.length) {
      return customList[Math.floor(Math.random() * customList.length)];
    }
  }
  // ── Fallback: defaults do plano ──
  const list = (TEMPLATES[type] || {})[premium ? 'premium' : 'basic'] || [];
  if (!list.length) return null;
  return list[Math.floor(Math.random() * list.length)];
}

function fillTemplate(tpl, vars) {
  let out = tpl;
  Object.entries(vars).forEach(([k,v]) => { out = out.split('{' + k + '}').join(String(v||'')); });
  return out;
}

// ── Throttle: máx N mensagens por instância em X ms ──
function checkThrottle(sd, instance, premium, maxPerWindow, windowMs) {
  if (!premium) return true; // sem throttle no básico (= maior risco de ban)
  const now = Date.now();
  sd.botThrottle = sd.botThrottle || {};
  sd.botThrottle[instance] = (sd.botThrottle[instance] || []).filter(ts => now - ts < windowMs);
  if (sd.botThrottle[instance].length >= maxPerWindow) return false;
  sd.botThrottle[instance].push(now);
  return true;
}

