function _waInjectZWSP(text){
  const ZWSP='\u200B';
  const t=String(text||'');
  if(t.length<10) return t;
  const positions=[];
  positions.push(Math.floor(t.length/3) + Math.floor(Math.random()*5));
  positions.push(Math.floor(t.length*2/3) + Math.floor(Math.random()*5));
  let r=t;
  positions.sort((a,b)=>b-a).forEach(p=>{ if(p>0&&p<r.length) r=r.slice(0,p)+ZWSP+r.slice(p); });
  return r;
}
function _waHash(str){ let h=0; for(let i=0;i<str.length;i++) h=((h<<5)-h+str.charCodeAt(i))|0; return Math.abs(h); }
function _waPickVariant(variants, seedStr){
  if(!variants||!variants.length) return null;
  const seed=_waHash(String(seedStr||'')+new Date().toISOString().slice(0,10));
  return variants[seed % variants.length];
}
async function _waCheckConnection(instance, apikey){
  const https=require('https');
  return new Promise(function(resolve){
    const r=https.request({
      hostname:\<REDACTED_PRIVATE_HOST>',
      path:'/instance/connectionState/'+encodeURIComponent(instance),
      method:'GET', headers:{'apikey':apikey}
    },function(re){
      let d=''; re.on('data',c=>d+=c);
      re.on('end',function(){
        try{ const j=JSON.parse(d||'{}'); const state=(j.instance&&j.instance.state)||j.state||''; resolve(state==='open'); }
        catch(_){ resolve(false); }
      });
    });
    r.on('error',function(){resolve(false);});
    r.setTimeout(5000,function(){r.destroy();resolve(false);});
    r.end();
  });
}
async function _waNumberExists(instance, apikey, phone){
  const https=require('https');
  return new Promise(function(resolve){
    const body=JSON.stringify({numbers:[phone]});
    const r=https.request({
      hostname:\<REDACTED_PRIVATE_HOST>',
