// Verifica conflitos de horário no Google Calendar
// e retorna os dados da reserva com valid=true/false
// n8n v2 syntax

const gcalItems = $input.all(); // eventos do GCal no período
const booking = $('Preparar reserva').first().json; // dados da reserva original

// IMPORTANTE: se a reserva já é inválida (LGPD, data passada, honeypot, etc.)
// passar através sem alterar — não sobrescrever valid:false com true
if (!booking.valid) {
  return [{ json: booking }];
}

const startMs = new Date(booking.start_iso).getTime();
const endMs   = new Date(booking.end_iso).getTime();

// Verificar sobreposição de horários com eventos existentes no GCal
let hasConflict = false;
let conflictInfo = '';

for (const item of gcalItems) {
  const ev = item.json;
  if (!ev || !ev.start) continue;
  const evStart = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00').getTime();
  const evEnd   = new Date(ev.end ? (ev.end.dateTime || ev.end.date + 'T23:59:59') : ev.start.dateTime).getTime();
  if (evStart < endMs && evEnd > startMs) {
    hasConflict = true;
    conflictInfo = ev.summary || 'Horário já agendado';
    break;
  }
}

if (hasConflict) {
  return [{ json: {
    ...booking,
    valid: false,
    errors: ['Horário indisponível: ' + conflictInfo + '. Por favor escolha outro horário.']
  }}];
}

return [{ json: { ...booking, valid: true, errors: [] } }];

