async function _waSendGuarded(opts){
  const s=opts.s, instance=String(opts.instance||''), phone=String(opts.phone||'').replace(/\D/g,'');
  const apikey=opts.apikey, eventType=String(opts.eventType||'generic');
  const skipConnectionCheck=!!opts.skipConnectionCheck;
  if(!instance||!phone||!apikey) return { ok:false, reason:'missing_params' };
  const now=Date.now();

  // ── 🚫 REFORÇO 3: Blocklist global (opt-out ou bloqueado) ──
  s.waBlocklist = s.waBlocklist || {};
  if (s.waBlocklist[phone]) {
    const bl = s.waBlocklist[phone];
    s.waStats=s.waStats||{}; s.waStats[instance]=s.waStats[instance]||{ createdAt:now, sends:[], skipped:[], strikes:0, pausedUntil:0, consecutiveFails:0 };
    s.waStats[instance].skipped.push({ts:now,phone,eventType,reason:'in_blocklist',blockReason:bl.reason});
    return { ok:false, reason:'in_blocklist', blockReason:bl.reason };
  }

  s.waStats=s.waStats||{};
  if(!s.waStats[instance]){
    s.waStats[instance]={ createdAt:now, sends:[], skipped:[], strikes:0, pausedUntil:0, consecutiveFails:0 };
  }
  const st=s.waStats[instance];
  if(!st.createdAt) st.createdAt=now;
  st.sends = (st.sends||[]).filter(x=>x.ts>now-30*86400000); // mantém 30d para per-client cap mensal
  st.skipped = (st.skipped||[]).filter(x=>x.ts>now-86400000);

  // ── 🚨 Auto-pause se tá pausado ──
  if(st.pausedUntil && st.pausedUntil > now){
    st.skipped.push({ts:now,phone,eventType,reason:'auto_paused'});
    return { ok:false, reason:'auto_paused', resumeAt:st.pausedUntil };
  }

  // ── 🌙 Quiet hours (22-7 BRT), exceto eventos críticos ──
  const QUIET_EXEMPT = ['confirmacao_reserva','confirmacao_reagendamento','admin_manual'];
  if (!QUIET_EXEMPT.includes(eventType)) {
    const hFmt = new Intl.DateTimeFormat('en-US',{ timeZone:'America/Sao_Paulo', hour:'numeric', hour12:false });
    const brHour = parseInt(hFmt.format(new Date(now)));
    if (brHour >= 22 || brHour < 7) {
      st.skipped.push({ts:now,phone,eventType,reason:'quiet_hours'});
      return { ok:false, reason:'quiet_hours', hour:brHour };
    }
  }

  // ── 📈 Warm-up progressivo ──
  const ageDays = Math.floor((now - st.createdAt) / 86400000);
  let dailyCap=80, hourlyCap=25;
  if (ageDays < 7)       { dailyCap=20; hourlyCap=8;  }
  else if (ageDays < 22) { dailyCap=50; hourlyCap=18; }
  const dayFmt = new Intl.DateTimeFormat('en-US',{ timeZone:'America/Sao_Paulo', weekday:'short' });
  const isSunday = dayFmt.format(new Date(now)) === 'Sun';
  if (isSunday) { dailyCap = Math.min(dailyCap, 30); hourlyCap = Math.min(hourlyCap, 12); }

  // ── 👤 REFORÇO 1+2: Per-client caps (soft + hard) ──
  // Eventos críticos podem passar do soft cap mas não do hard
  const HIGH_PRIORITY = ['confirmacao_reserva','confirmacao_reagendamento','admin_manual'];
  const isHighPriority = HIGH_PRIORITY.includes(eventType);

  const sentToClient24h = st.sends.filter(x => x.phone === phone && x.ts > now - 86400000).length;
  const sentToClient30d = st.sends.filter(x => x.phone === phone && x.ts > now - 30*86400000).length;

  // Hard caps (proteção absoluta)
  if (sentToClient24h >= 5) {
    st.skipped.push({ts:now,phone,eventType,reason:'client_daily_hard_cap'});
    return { ok:false, reason:'client_daily_hard_cap', count:sentToClient24h };
  }
  if (sentToClient30d >= 20) {
    st.skipped.push({ts:now,phone,eventType,reason:'client_monthly_hard_cap'});
    return { ok:false, reason:'client_monthly_hard_cap', count:sentToClient30d };
  }

  // Soft caps (eventos não-críticos)
  if (sentToClient24h >= 3 && !isHighPriority) {
    st.skipped.push({ts:now,phone,eventType,reason:'client_daily_soft_cap'});
    return { ok:false, reason:'client_daily_soft_cap', count:sentToClient24h };
  }
  if (sentToClient30d >= 12 && !isHighPriority) {
    st.skipped.push({ts:now,phone,eventType,reason:'client_monthly_soft_cap'});
    return { ok:false, reason:'client_monthly_soft_cap', count:sentToClient30d };
  }

  // ── 📊 Caps globais da instância ──
  // Recalcula sends 24h (já filtrado pra 30d acima)
  const sends24h = st.sends.filter(x => x.ts > now - 86400000);
  if(sends24h.length>=dailyCap){
    st.skipped.push({ts:now,phone,eventType,reason:'daily_cap'});
    return { ok:false, reason:'daily_cap', count:sends24h.length, cap:dailyCap };
  }
  const lastHour=sends24h.filter(x=>x.ts>now-3600000);
  if(lastHour.length>=hourlyCap){
    st.skipped.push({ts:now,phone,eventType,reason:'hourly_cap'});
    return { ok:false, reason:'hourly_cap', count:lastHour.length, cap:hourlyCap };
  }
  // Cooldown 2h mesmo evento mesmo destinatário
  const dup=st.sends.find(x=>x.phone===phone&&x.eventType===eventType&&x.ts>now-7200000);
  if(dup){
    st.skipped.push({ts:now,phone,eventType,reason:'recipient_cooldown'});
    return { ok:false, reason:'recipient_cooldown', sinceMs:now-dup.ts };
  }
  const lastMin=sends24h.filter(x=>x.ts>now-60000);
  if(lastMin.length>=3){
    st.skipped.push({ts:now,phone,eventType,reason:'burst_protection'});
    return { ok:false, reason:'burst_protection', count:lastMin.length };
  }
  if(lastMin.length>=1){
    const delayMs=3000+Math.floor(Math.random()*5000);
    await new Promise(function(r){setTimeout(r,delayMs);});
  }

  if(!skipConnectionCheck){
    const isConn = await _waCheckConnection(instance, apikey);
    if(!isConn){
      st.skipped.push({ts:now,phone,eventType,reason:'instance_disconnected'});
      st.strikes=(st.strikes||0)+1;
      st.consecutiveFails=(st.consecutiveFails||0)+1;
      if(st.consecutiveFails>=3){
        st.pausedUntil = now + 24*3600*1000;
        await _waTgAlert(s, instance, 'connection_lost', st.consecutiveFails, st.pausedUntil);
      }
      return { ok:false, reason:'instance_disconnected', consecutiveFails:st.consecutiveFails };
    }
  }

  const finalText=_waInjectZWSP(String(opts.text||''));
  const https=require('https');
  function _httpPost(host,path,headers,body){return new Promise(function(resolve,reject){
    const r=https.request({hostname:host,path:path,method:'POST',headers:headers||{}},re=>{
      let d=''; re.on('data',c=>d+=c); re.on('end',()=>resolve({status:re.statusCode,body:d}));
    });
    r.on('error',reject); if(body) r.write(Buffer.from(body,'utf8')); r.end();
  });}
  try{
    const body=JSON.stringify({number:phone,text:finalText,delay:opts.delay||800});
    const res=await _httpPost(\<REDACTED_PRIVATE_HOST>','/message/sendText/'+encodeURIComponent(instance),
      {'apikey':apikey,'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)},body);
    if(res.status<200||res.status>=300){
      st.strikes=(st.strikes||0)+1;
      st.consecutiveFails=(st.consecutiveFails||0)+1;
      st.skipped.push({ts:now,phone,eventType,reason:'send_error',status:res.status});

      // ── 🚫 REFORÇO 3: Per-phone failure tracking → blocklist após 3 ──
      s.waPhoneFails = s.waPhoneFails || {};
      const phoneKey = phone;
      if (!s.waPhoneFails[phoneKey]) s.waPhoneFails[phoneKey] = { count:0, lastTs:0, instance };
      s.waPhoneFails[phoneKey].count++;
      s.waPhoneFails[phoneKey].lastTs = now;
      if (s.waPhoneFails[phoneKey].count >= 3) {
        s.waBlocklist[phone] = { reason:'consecutive_failures', ts:now, instance };
        delete s.waPhoneFails[phoneKey];
      }

      if(st.consecutiveFails>=3){
        st.pausedUntil = now + 24*3600*1000;
        await _waTgAlert(s, instance, 'send_errors', st.consecutiveFails, st.pausedUntil);
      }
      return { ok:false, reason:'send_error', status:res.status, body:String(res.body).slice(0,200), consecutiveFails:st.consecutiveFails };
    }
    // SUCCESS
    st.sends.push({ts:now,phone,eventType});
    st.consecutiveFails=0;
    if (s.waPhoneFails && s.waPhoneFails[phone]) delete s.waPhoneFails[phone];
    return { ok:true, sent:true };
  }catch(e){
    st.strikes=(st.strikes||0)+1;
    st.consecutiveFails=(st.consecutiveFails||0)+1;
    if(st.consecutiveFails>=3){
      st.pausedUntil = now + 24*3600*1000;
      await _waTgAlert(s, instance, 'exception', st.consecutiveFails, st.pausedUntil);
    }
    return { ok:false, reason:'exception', error:String(e.message||e) };
  }
}
async function _waTgAlert(s, instance, reason, fails, resumeAt){
  try {
    const cfg = s.platformConfig || {};
    const tgToken = cfg.alertsTgToken || cfg.backupTgToken;
    const tgChatId = cfg.alertsTgChatId || cfg.backupTgChatId;
    if (!tgToken || !tgChatId) return;
    const https = require('https');
    const resumeStr = new Date(resumeAt).toLocaleString('pt-BR',{ timeZone:'America/Sao_Paulo' });
    const msg = '🚨 *Instância WhatsApp PAUSADA*\n\n' +
      '📱 Instância: `' + instance + '`\n' +
      '❌ Motivo: ' + reason + '\n' +
      '🔢 Falhas consecutivas: ' + fails + '\n' +
      '⏰ Resume em: ' + resumeStr;
    const body = JSON.stringify({ chat_id: tgChatId, text: msg, parse_mode: 'Markdown' });
    await new Promise(function(resolve){
      const r = https.request({ hostname:'api.telegram.org', path:'/bot'+tgToken+'/sendMessage', method:'POST',
        headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)} }, function(re){
        let d=''; re.on('data',c=>d+=c); re.on('end',resolve);
      });
      r.on('error', resolve);
      r.setTimeout(8000, function(){ r.destroy(); resolve(); });
      r.write(body); r.end();
    });
  } catch(_) {}
}

