const brl = v => 'R$ ' + Number(v||0).toLocaleString('pt-BR');

function todayDate() { return new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' }); }
function plusDays(d, n) { const x = new Date(d+'T12:00:00'); x.setDate(x.getDate()+n); return x.toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'}); }
function fmtDateBR(d) { return new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',timeZone:'America/Sao_Paulo'}); }
function parseDateUser(str) {
  if (!str) return null;
  str = str.toLowerCase().trim();
  if (str === 'hoje') return todayDate();
  if (str === 'amanha' || str === 'amanhã') return plusDays(todayDate(), 1);
  if (str === 'depois de amanha' || str === 'depois de amanhã') return plusDays(todayDate(), 2);
  // Dia da semana próximo
  const weekdays = { 'domingo':0,'segunda':1,'terca':2,'terça':2,'quarta':3,'quinta':4,'sexta':5,'sabado':6,'sábado':6 };
  for (const [k,v] of Object.entries(weekdays)) {
    if (str === k || str.startsWith(k+' ')) {
      const today = new Date();
      let diff = v - today.getDay();
      if (diff <= 0) diff += 7;
      return plusDays(todayDate(), diff);
    }
  }
  // DD/MM ou DD/MM/YYYY ou YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  const m = str.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (m) {
    const d = m[1].padStart(2,'0'), mo = m[2].padStart(2,'0');
    const y = m[3] ? (m[3].length===2 ? '20'+m[3] : m[3]) : new Date().getFullYear();
    return y + '-' + mo + '-' + d;
  }
  return null;
}

