};
function getBotTier(sd) {
  const cs = sd.clients || {};
  const ids = Object.keys(cs).filter(id => id !== 'superadmin');
  // single-client (provisioned workflow) ou default
  const clientId = ids.length === 1 ? ids[0] : 'default';
  const c = cs[clientId] || {};
  let plan = c.plan || 'profissional';
  if (c.trialExpires && c.trialExpires > Date.now()) plan = c.planTrial || 'profissional';
  const features = PLAN_FEATURES_BOT[plan] || PLAN_FEATURES_BOT.profissional;
  return { plan, features, premium: features.indexOf('bot_premium') >= 0 };
}

