function _httpReq(opts) {
  return new Promise((resolve, reject) => {
    const isHttps = (opts.url || '').startsWith('https://');
    const u = new URL(opts.url);
    const isJSONBody = opts.body && typeof opts.body !== 'string';
    const bodyStr = opts.body ? (isJSONBody ? JSON.stringify(opts.body) : opts.body) : null;
    const hdr = Object.assign({}, opts.headers || {});
    if (bodyStr && !hdr['Content-Type'] && !hdr['content-type']) hdr['Content-Type'] = 'application/json';
    if (bodyStr) hdr['Content-Length'] = Buffer.byteLength(bodyStr, 'utf8');
    const mod = require(isHttps ? 'https' : 'http');
    const r = mod.request({
      hostname: u.hostname,
      port: u.port || (isHttps ? 443 : 80),
      path: u.pathname + (u.search || ''),
      method: opts.method || 'GET',
      headers: hdr
    }, res => {
      let d = ''; res.on('data', c => d += c);
      res.on('end', () => {
        let parsed = d;
        try { if (d && (d.startsWith('{') || d.startsWith('['))) parsed = JSON.parse(d); } catch(_) {}
        resolve(parsed);
      });
    });
    r.on('error', reject);
    if (bodyStr) r.write(bodyStr);
    r.end();
  });
}

