// Usa require('https') — disponível no sandbox do n8n (fetch e $helpers não disponíveis no cron)
function httpGet(url) {
  return new Promise(function(resolve, reject) {
    var https = require('https');
    var URL2 = require('url').URL;
    var u = new URL2(url);
    var opts = { hostname: u.hostname, path: u.pathname + u.search, method: 'GET' };
    var req = https.request(opts, function(res) {
      var body = '';
      res.on('data', function(c) { body += c; });
      res.on('end', function() { resolve({ statusCode: res.statusCode, body: body }); });
    });
    req.on('error', reject);
    req.end();
  });
}

