  // Eventos críticos podem passar do soft cap mas não do hard
  const HIGH_PRIORITY = ['confirmacao_reserva','confirmacao_reagendamento','admin_manual'];
  const isHighPriority = HIGH_PRIORITY.includes(eventType);

  const sentToClient24h = st.sends.filter(x => x.phone === phone && x.ts > now - 86400000).length;
  const sentToClient30d = st.sends.filter(x => x.phone === phone && x.ts > now - 30*86400000).length;

  // Hard caps (proteção absoluta)
  if (sentToClient24h >= 5) {
