const _https = require('https');
const _http  = require('http');
function hreq(opts) {
  return new Promise((resolve, reject) => {
    const isHttps = String(opts.url).startsWith('https://');
    const lib = isHttps ? _https : _http;
    const u = new URL(opts.url);
    const body = opts.body ? (typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body)) : null;
    const headers = Object.assign({}, opts.headers || {});
    if (body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(body);
    const reqOpts = {
      hostname: u.hostname,
      port: u.port || (isHttps ? 443 : 80),
      path: u.pathname + (u.search || ''),
      method: opts.method || 'GET',
      headers
    };
    const r = lib.request(reqOpts, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        try {
          const parsed = res.headers['content-type'] && res.headers['content-type'].includes('json') ? JSON.parse(data) : data;
          resolve(opts.returnFullResponse ? { statusCode: res.statusCode, body: parsed, headers: res.headers } : parsed);
        } catch(e) {
          resolve(opts.returnFullResponse ? { statusCode: res.statusCode, body: data, headers: res.headers } : data);
        }
      });
    });
    r.on('error', reject);
    if (body) r.write(body);
    r.end();
  });
}

