// ── HTTP helper ────────────────────────────────────────────────────────────
function hreq(host, path, method, headers, body) {
  return new Promise((resolve, reject) => {
    const opts = { hostname: host, path, method: method || 'GET', headers: headers || {} };
    const r = https.request(opts, res => {
      let d = ''; res.on('data', c => d += c);
      res.on('end', () => resolve({ status: res.statusCode, body: d }));
    });
    r.on('error', reject);
    if (body) r.write(Buffer.from(body, 'utf8'));
    r.end();
  });
}

