  const desiredDay=d.getDate();
  const nx=new Date(targetYear,targetMonth,1,12,0,0);
  const lastDayOfMonth=new Date(targetYear,targetMonth+1,0).getDate();
  nx.setDate(Math.min(desiredDay,lastDayOfMonth));
  return nx.getTime();
}

