async function _tgNotify(s, text) {
  const cfg = s.platformConfig || {};
  const token = cfg.alertsTgToken || cfg.backupTgToken;
  const chatId = cfg.alertsTgChatId || cfg.backupTgChatId;
  if (!token || !chatId) return { ok:false, reason:'not_configured' };
  const https = require('https');
  return new Promise(function(resolve){
    const body = JSON.stringify({ chat_id: chatId, text: text, parse_mode: 'Markdown', disable_web_page_preview: true });
    const r = https.request({
      hostname: 'api.telegram.org', path: '/bot' + token + '/sendMessage', method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
    }, function(res){
      let d=''; res.on('data', c => d += c);
      res.on('end', function(){ try { resolve({ ok: JSON.parse(d).ok }); } catch(e) { resolve({ ok:false }); } });
    });
    r.on('error', function(){ resolve({ ok:false }); });
    r.setTimeout(10000, function(){ r.destroy(); resolve({ ok:false, reason:'timeout' }); });
    r.write(body); r.end();
  });
}

