const ASAAS_BASE = asaas.environment === 'production' ? 'api.asaas.com' : 'sandbox.asaas.com';
const ASAAS_PATH_PREFIX = asaas.environment === 'production' ? '/v3' : '/api/v3';

function asaasCall(method, path, body){
  return new Promise(function(resolve, reject){
    const data = body ? JSON.stringify(body) : null;
    const opts = {
      hostname: ASAAS_BASE,
      path: ASAAS_PATH_PREFIX + path,
      method: method,
      headers: {
        'Content-Type': 'application/json',
        'access_token': asaas.apiKey,
        'User-Agent': 'AgendaBarber/1.0'
      }
    };
    if(data) opts.headers['Content-Length'] = Buffer.byteLength(data);
    const r = https_lib.request(opts, function(re){
      let d = ''; re.on('data', c => d += c);
      re.on('end', function(){
        try { resolve({ status: re.statusCode, data: JSON.parse(d || '{}') }); }
        catch(e){ resolve({ status: re.statusCode, data: { _raw: d } }); }
      });
    });
    r.on('error', reject);
    r.setTimeout(15000, function(){ r.destroy(); reject(new Error('asaas_timeout')); });
    if(data) r.write(data);
    r.end();
  });
}

s.clients = s.clients || {};
