    return [{ json: { ok:false, message:'Erro ao criar cobrança: ' + (createPayment.data.errors?.[0]?.description || 'desconhecido'), asaasError: createPayment.data } }];
  }

  const payment = createPayment.data;

  // 3. Busca QR Pix
  const qr = await asaasCall('GET', '/payments/' + payment.id + '/pixQrCode');
  let qrCode = null, qrPayload = null;
  if(qr.status === 200){
