    qrPayload = qr.data.payload || null;
  }

  // 4. Salva no static data como pendente
  clientData.payments = clientData.payments || [];
  clientData.payments.unshift({
    id: payment.id,
    plan: planId,
    value: plan.value,
    status: 'PENDING',
    method: 'PIX',
    dueDate: dueDateStr,
