  return [{ json: {
    ok: true,
    payment: {
      id: payment.id,
      value: plan.value,
      plan: planId,
      planLabel: plan.label,
      dueDate: dueDateStr,
      invoiceUrl: payment.invoiceUrl,
      qrCode: qrCode,
      qrPayload: qrPayload
    },
    message: 'Cobrança criada! Escaneie o QR ou copie o código Pix.'
  } }];

