// ════ HEALTH REPORT PRO MATEUS (Telegram, SEM PII de cliente final) ════
function buildHealthReport() {
  const clients = Object.entries(s.clients||{}).filter(function(e){ return e[0]!=='default' && e[0]!=='superadmin'; });
  let paid=0, trial=0, warning=0, grace=0, expired=0;
  const nextPayments = [];
  const expiringTrials = [];
  const PRICE_PER_MONTH = 119; // ajuste se mudar o preço

  clients.forEach(function(entry){
    const cid=entry[0], c=entry[1];
    const name = (c.businessConfig||{}).name || cid;
    if (c.subscriptionActive) {
      paid++;
      if (c.paidUntil) {
        const days = Math.ceil((c.paidUntil - _now)/86400000);
        if (days <= 14 && days >= 0) nextPayments.push({ name:name, days:days });
      }
    } else if (c.trialExpires) {
      const days = Math.ceil((c.trialExpires - _now)/86400000);
      if (days < -3) expired++;
      else if (days < 0) { grace++; expiringTrials.push({ name:name, days:days, label:'carência' }); }
      else if (days < 7) { warning++; expiringTrials.push({ name:name, days:days, label:'aviso' }); }
      else trial++;
    }
  });

  const mrr = paid * PRICE_PER_MONTH;

  // Stats operacionais — só agregados
  let todayCmdOpen=0, todayCmdClosed=0, totalCmdEver=0;
  clients.forEach(function(e){
    const c = e[1];
    Object.values(c.comandas||{}).forEach(function(cmd){
      totalCmdEver++;
      if (cmd.openedAt >= todayStart) todayCmdOpen++;
      if (cmd.status==='closed' && cmd.closedAt >= todayStart) todayCmdClosed++;
    });
  });

  // WhatsApp
  let waActive=0, waStrikes=0, waSentToday=0, waSkipped=0;
  Object.values(s.waStats||{}).forEach(function(st){
    waActive++;
    waStrikes += st.strikes||0;
    waSentToday += (st.sends||[]).filter(function(x){return x.ts>=todayStart;}).length;
    waSkipped += (st.skipped||[]).filter(function(x){return x.ts>=todayStart;}).length;
  });

  // Audit alerts
  const todayLogs = (s.auditLog||[]).filter(function(e){return e.ts>=todayStart;});
  const failedLogins = todayLogs.filter(function(e){return e.action==='login_failed';}).length;
  const lockouts = todayLogs.filter(function(e){return e.action==='login_locked_user' || e.action==='login_locked_ip';}).length;
  const newAccounts = todayLogs.filter(function(e){return e.action==='account_created';}).length;
  const subActivations = todayLogs.filter(function(e){return e.action==='subscription_activated';}).length;

  // CVE
  const lastCve = (s.cveAlerts||[])[0];

  // Backup
  const totalBkSize = Object.values(s.backups||{}).reduce(function(sum,b){return sum + (b.sizeKb||0);}, 0);

  // Compor mensagem (Markdown Telegram)
  let m = '🎯 *AgendaBarber — Resumo ' + today + '*\n\n';

  m += '💰 *RECEITA*\n';
  m += '  • ' + paid + ' pagos (~R\\$ ' + mrr.toLocaleString('pt-BR') + '/mês MRR)\n';
  m += '  • +' + subActivations + ' assinatura(s) ativada(s) hoje\n';
  m += '  • +' + newAccounts + ' nova(s) conta(s) criada(s)\n\n';

  if (nextPayments.length) {
    m += '⏰ *PAGAMENTOS PRÓXIMOS*\n';
    nextPayments.sort(function(a,b){return a.days-b.days;}).slice(0,5).forEach(function(p){
      m += '  • ' + p.name + ': ' + (p.days===0 ? 'HOJE' : 'vence em ' + p.days + 'd') + '\n';
    });
    m += '\n';
  }

  if (expiringTrials.length) {
    m += '🟡 *TRIALS VENCENDO*\n';
    expiringTrials.sort(function(a,b){return a.days-b.days;}).slice(0,5).forEach(function(t){
      const label = t.days < 0 ? 'há ' + Math.abs(t.days) + 'd (' + t.label + ')' : t.days + 'd';
      m += '  • ' + t.name + ': ' + label + '\n';
    });
    m += '\n';
  }

  m += '📊 *OPERACIONAL HOJE*\n';
  m += '  • ' + todayCmdOpen + ' comandas abertas\n';
  m += '  • ' + todayCmdClosed + ' comandas fechadas\n';
  m += '  • ' + waSentToday + ' WhatsApp enviados (' + waActive + ' instâncias)\n';
  if (waSkipped > 0) m += '  • ' + waSkipped + ' WA pulados (guardrails)\n';
  m += '\n';

  m += '🚨 *ALERTAS*\n';
  m += '  • ' + failedLogins + ' falhas de login\n';
  m += '  • ' + lockouts + ' bloqueios por rate-limit\n';
  m += '  • ' + waStrikes + ' strikes WA acumulados\n';
  if (lastCve) m += '  • CVE scan: ' + lastCve.findingsCount + ' findings em ' + lastCve.dateKey + '\n';
  m += '\n';

  m += '👥 *TRIAL PIPELINE*\n';
  m += '  • Em trial ativo: ' + trial + '\n';
  m += '  • Aviso (<7d): ' + warning + '\n';
  m += '  • Carência: ' + grace + '\n';
  m += '  • Expirados: ' + expired + '\n\n';

  m += '🛡️ *SAÚDE DO SISTEMA*\n';
  m += '  • Sessões ativas: ' + Object.keys(s.sessions||{}).length + '\n';
  m += '  • Backups in-system: ' + Object.keys(s.backups||{}).length + ' (' + totalBkSize + 'KB)\n';
  m += '  • Audit log: ' + (s.auditLog||[]).length + ' eventos\n';
  m += '  • Total comandas all-time: ' + totalCmdEver + '\n';

  return m;
}

// ════ HEALTH REPORT VIA TELEGRAM ════
async function sendTelegramText(token, chatId, text) {
  if (!token || !chatId) return { ok:false, reason:'not_configured' };
  return new Promise(function(resolve){
    const body = JSON.stringify({ chat_id: chatId, text: text, parse_mode: 'Markdown', disable_web_page_preview: true });
    const r = https.request({
      hostname: 'api.telegram.org',
      path: '/bot' + token + '/sendMessage',
      method: 'POST',
      headers: { 'Content-Type':'application/json', 'Content-Length': Buffer.byteLength(body) }
    }, function(res){
      let d=''; res.on('data', c => d += c);
      res.on('end', function(){ try { resolve({ ok:JSON.parse(d).ok }); } catch(e){ resolve({ ok:false }); } });
    });
    r.on('error', function(){ resolve({ ok:false }); });
    r.setTimeout(15000, function(){ r.destroy(); resolve({ ok:false }); });
    r.write(body); r.end();
  });
}

