// ════ PER-CLIENT BACKUP VIA EMAIL (Resend) ════
async function sendEmailResend(apiKey, fromAddr, toAddr, subject, html, attachment) {
  return new Promise(function(resolve){
    const payload = { from: fromAddr, to: [toAddr], subject: subject, html: html };
    if (attachment) payload.attachments = [{ filename: attachment.filename, content: attachment.contentBase64 }];
    const body = JSON.stringify(payload);
    const r = https.request({
      hostname:'api.resend.com', path:'/emails', method:'POST',
      headers: {
        'Authorization': 'Bearer ' + apiKey,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      }
    }, function(res){
      let d=''; res.on('data', c => d += c);
      res.on('end', function(){ try{ resolve({ status:res.statusCode, body:JSON.parse(d) }); }catch(e){ resolve({ status:res.statusCode, body:{ raw:d } }); } });
    });
    r.on('error', function(e){ resolve({ status:0, error:e.message }); });
    r.setTimeout(30000, function(){ r.destroy(); resolve({ status:0, error:'timeout' }); });
    r.write(body); r.end();
  });
}

function clientCsv(client, clientId) {
  // Comandas em CSV
  let csv = 'Data,Cliente,Telefone,Barbeiro,Total,Pagamento,Status\n';
  Object.values(client.comandas||{}).forEach(function(c){
    const dt = c.closedAt ? new Date(c.closedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}) :
                            new Date(c.openedAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});
    csv += '"' + dt + '","' + (c.clienteName||'').replace(/"/g,'""') + '","' + (c.clientePhone||'') + '","' +
           (c.barber||'').replace(/"/g,'""') + '","' + (c.total||0) + '","' + (c.paymentMethod||'') + '","' + c.status + '"\n';
  });
  return csv;
}

