    '<div style="background:#f5f5f5;padding:15px;border-radius:8px;margin:15px 0">' +
      '<strong>📊 Resumo:</strong><br>' +
      '• Comandas: ' + summary.totalCmd + ' (abertas ' + summary.openCmd + ', fechadas ' + summary.closedCmd + ')<br>' +
      '• Despesas: ' + summary.totalDesp + '<br>' +
      '• Clientes únicos: ' + summary.totalCli + '<br>' +
      '• Faturamento mês: R$ ' + summary.revenueMonth.toFixed(2).replace('.',',') +
    '</div>' +
    '<p>📎 <strong>Anexo:</strong> backup-' + clientId + '-' + dateKey + '.csv (todas comandas)</p>' +
    '<hr style="border:none;border-top:1px solid #ddd;margin:20px 0">' +
