    'Configurado por você na aba "Infra" do superadmin. ' +
    'Para parar de receber: peça ao administrador da plataforma para limpar o campo backupEmail.</p>' +
    '</div>';
}

const resendApiKey = s.platformConfig.resendApiKey;
const resendFrom = s.platformConfig.resendFrom || \<REDACTED_EMAIL>'; // ajustar pro domínio verificado
const emailResults = [];

if (resendApiKey) {
  const clientList = Object.entries(s.clients||{}).filter(function(e){
    return e[0]!=='default' && e[0]!=='superadmin' && e[1].businessConfig && e[1].businessConfig.backupEmail;
  });

  for (const entry of clientList) {
    const clientId = entry[0];
    const client = entry[1];
    const email = client.businessConfig.backupEmail;

    // Compute summary
    const summary = {
      totalCmd: Object.keys(client.comandas||{}).length,
      openCmd: 0, closedCmd: 0,
      totalDesp: Object.keys(client.despesas||{}).length,
      totalCli: Object.keys(client.clientes||{}).length,
      revenueMonth: 0
    };
    const monthStart = new Date(_now); monthStart.setDate(1); monthStart.setHours(0,0,0,0);
    Object.values(client.comandas||{}).forEach(function(c){
      if (c.status==='open') summary.openCmd++;
      else if (c.status==='closed') {
        summary.closedCmd++;
        if (c.closedAt >= monthStart.getTime()) summary.revenueMonth += (c.total||0);
      }
    });

    const csv = clientCsv(client, clientId);
    const csvBase64 = Buffer.from(csv, 'utf8').toString('base64');
    const html = clientBackupHtml(client, clientId, summary);

    const res = await sendEmailResend(
