      { filename: 'backup-' + clientId + '-' + dateKey + '.csv', contentBase64: csvBase64 }
    );
    emailResults.push({ clientId, email, status:res.status, ok: res.status===200 });

    // Delay entre envios pra não saturar Resend
    await new Promise(function(r){ setTimeout(r, 1500); });
  }
}

