// ── Helper HTTP GET com timeout ──
function httpGetJson(host, path) {
  return new Promise(function(resolve){
    const r = https.request({
      hostname: host, path, method: 'GET',
      headers: { 'User-Agent': 'AgendaBarber-CVE-Scanner/1.0', 'Accept': 'application/json' }
    }, function(res){
      let d=''; res.on('data', c => d += c);
      res.on('end', function(){
        try { resolve({ status: res.statusCode, json: JSON.parse(d) }); }
        catch(e) { resolve({ status: res.statusCode, json: null, raw: String(d).slice(0,300) }); }
      });
    });
    r.on('error', function(e){ resolve({ status: 0, error: String(e.message||e) }); });
    r.setTimeout(15000, function(){ r.destroy(); resolve({ status: 0, error: 'timeout' }); });
    r.end();
  });
}

// ── Helper Telegram sendMessage ──
async function sendTelegram(token, chatId, text) {
  if (!token || !chatId) return { ok:false, reason:'not_configured' };
  return new Promise(function(resolve){
    const body = JSON.stringify({
      chat_id: chatId,
      text: text,
      parse_mode: 'Markdown',
      disable_web_page_preview: true
    });
    const r = https.request({
      hostname: 'api.telegram.org',
      path: '/bot' + token + '/sendMessage',
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
    }, function(res){
      let d=''; res.on('data', c => d += c);
      res.on('end', function(){
        try { const p = JSON.parse(d); resolve({ ok: !!p.ok, raw: p }); }
        catch(e) { resolve({ ok:false, raw: String(d).slice(0,200) }); }
      });
    });
    r.on('error', function(e){ resolve({ ok:false, error: String(e.message||e) }); });
    r.setTimeout(15000, function(){ r.destroy(); resolve({ ok:false, error:'timeout' }); });
    r.write(body); r.end();
  });
}

