    const path = '/rest/json/cves/2.0' +
      '?keywordSearch=' + encodeURIComponent(kw) +
      '&pubStartDate=' + encodeURIComponent(since) +
      '&pubEndDate=' + encodeURIComponent(until) +
      '&resultsPerPage=' + MAX_PER_KEYWORD;
    const res = await httpGetJson('services.nvd.nist.gov', path);
    if (res.status !== 200 || !res.json) {
      errors.push({ stack: item.name, kw, status: res.status, error: res.error || (res.raw || '').slice(0,80) });
      continue;
    }
    const vulns = res.json.vulnerabilities || [];
    for (const v of vulns) {
      const cve = v.cve || {};
      const id = cve.id;
      if (!id || s.cveAlertedIds[id]) continue;
      const metrics = cve.metrics || {};
      let cvss = null, severity = null;
      if (metrics.cvssMetricV31 && metrics.cvssMetricV31[0]) {
        cvss = metrics.cvssMetricV31[0].cvssData?.baseScore || null;
        severity = metrics.cvssMetricV31[0].cvssData?.baseSeverity || null;
      } else if (metrics.cvssMetricV30 && metrics.cvssMetricV30[0]) {
        cvss = metrics.cvssMetricV30[0].cvssData?.baseScore || null;
        severity = metrics.cvssMetricV30[0].cvssData?.baseSeverity || null;
      } else if (metrics.cvssMetricV2 && metrics.cvssMetricV2[0]) {
        cvss = metrics.cvssMetricV2[0].cvssData?.baseScore || null;
      }
      if (!cvss || cvss < MIN_CVSS) continue;
      const desc = (cve.descriptions || []).find(function(d){ return d.lang === 'en'; });
      findings.push({
        id, cvss, severity: severity || (cvss >= 9 ? 'CRITICAL' : 'HIGH'),
        stack: item.name,
        published: cve.published,
        descShort: (desc?.value || '').slice(0, 280)
      });
      s.cveAlertedIds[id] = _now;
    }
    // Pequeno delay pra não bater no rate limit da NVD (5 req / 30s)
    await new Promise(function(r){ setTimeout(r, 6500); });
  }
}

// ── Ordena por severidade ──
findings.sort(function(a,b){ return (b.cvss||0) - (a.cvss||0); });

