  msg += '📅 ' + new Date(_now).toLocaleString('pt-BR', { timeZone:'America/Sao_Paulo' }) + '\n';
  msg += '🚨 *' + findings.length + ' vulnerabilidade(s)* (CVSS ≥ ' + MIN_CVSS + ')\n\n';
  findings.slice(0, 8).forEach(function(f){
    const emoji = f.cvss >= 9 ? '🔴' : '🟠';
    msg += emoji + ' *' + f.id + '* — ' + f.stack + '\n';
    msg += '   CVSS ' + f.cvss + ' (' + f.severity + ')\n';
    msg += '   ' + f.descShort.slice(0, 160) + (f.descShort.length > 160 ? '...' : '') + '\n';
    msg += '   [Detalhes](https://nvd.nist.gov/vuln/detail/' + f.id + ')\n\n';
  });
  if (findings.length > 8) msg += '_+ ' + (findings.length - 8) + ' outras…_';
  tgResult = await sendTelegram(tgToken, tgChatId, msg);
}

return [{ json: {
