function _waInjectZWSP(text){
  const ZWSP='\u200B';
  const t=String(text||'');
  if(t.length<10) return t;
  const positions=[Math.floor(t.length/3) + Math.floor(Math.random()*5), Math.floor(t.length*2/3) + Math.floor(Math.random()*5)];
  let r=t;
  positions.sort((a,b)=>b-a).forEach(p=>{ if(p>0&&p<r.length) r=r.slice(0,p)+ZWSP+r.slice(p); });
  return r;
}
