const msgLower = message.toLowerCase();
if (SPAM_WORDS.some(w => msgLower.includes(w))) {
  return [{ json: { ok:false, message:'Mensagem não pode ser enviada.' }}];
}

// Rate limit: 1 msg/phone/hora
s.clients = s.clients || {};
s.clients[clientId] = s.clients[clientId] || {};
s.clients[clientId].clientMessages = s.clients[clientId].clientMessages || [];
const recent = s.clients[clientId].clientMessages.find(m => m.phone === phone && m.ts > _now - 3600000);
if (recent) {
  const waitMin = Math.ceil((3600000 - (_now - recent.ts)) / 60000);
  return [{ json: { ok:false, message:'Você enviou uma mensagem recentemente. Tente novamente em ' + waitMin + ' min.' }}];
}

// Daily limit por cliente: max 3 msgs/dia da mesma barbearia
const today = (s.clients[clientId].clientMessages || []).filter(m => m.ts > _now - 86400000).length;
if (today >= 30) {
  return [{ json: { ok:false, message:'A barbearia recebeu muitas mensagens hoje. Tente amanhã.' }}];
}

// Salva mensagem
const msgId = 'msg-' + _now.toString(36) + Math.random().toString(36).slice(2,5);
const newMsg = {
  id: msgId, ts: _now, phone, name, message,
  urgent, status: 'unread',
  receivedAt: new Date(_now).toLocaleString('pt-BR', { timeZone:'America/Sao_Paulo' })
};
s.clients[clientId].clientMessages.unshift(newMsg);
if (s.clients[clientId].clientMessages.length > 200) {
  s.clients[clientId].clientMessages = s.clients[clientId].clientMessages.slice(0, 200);
}

// Audit
s.auditLog = s.auditLog || [];
s.auditLog.push({ ts: _now, action: 'client_message_received', user: phone, detail: { clientId, urgent, msgId } });
if (s.auditLog.length > 2000) s.auditLog = s.auditLog.slice(-2000);

// Notifica via WhatsApp do dono via Evolution
const cfg = (s.clients[clientId] && s.clients[clientId].businessConfig) || s.businessConfig || {};
const adminPhone = String(cfg.adminPhone || cfg.whatsapp || '').replace(/\D/g,'');
const evolInst = String(cfg.evolutionInstance || 'estudo');
const evolKey = (s.platformConfig||{}).evolutionKey || 'f7aaaba7593506765800c7d58133007a';

let waSent = false;
if (adminPhone && evolInst) {
  const urgentTag = urgent ? '🚨 *MENSAGEM URGENTE*\n\n' : '📩 *Nova mensagem de cliente*\n\n';
  const tgMsg = urgentTag +
    '👤 ' + name + '\n' +
    '📱 ' + phone + '\n\n' +
    '💬 _' + message.replace(/[*_~`]/g,'') + '_\n\n' +
    '↗️ Responder: wa.me/' + phone + '\n' +
    '📋 ' + ((s.clients[clientId].businessConfig||{}).name || 'Barbearia');
  const r = await _waSendUrgent(s, evolInst, evolKey, adminPhone, tgMsg, urgent);
  waSent = r.ok;
}

return [{ json: {
  ok: true,
  msgId,
  notificationSent: waSent,
  message: 'Mensagem enviada com sucesso! O barbeiro responderá em breve.'
}}];
